[{"kind":"meta","branch":"headers","message":"Security headers: strict-transport-security, x-content-type-options, referrer-policy, permissions-policy"},{"kind":"file","path":"deploy/nginx/sites-available/afrodidact.conf","before":"    server_name afrodidact.org;","text":"    # The protective headers this site was missing, proposed by Elixir.
    # Only the safe set: a Content-Security-Policy is a per-site decision.
    add_header strict-transport-security "max-age=604800" always;
    add_header x-content-type-options "nosniff" always;
    add_header referrer-policy "strict-origin-when-cross-origin" always;
    add_header permissions-policy "camera=(), microphone=()" always;"}]
